command:
/**
 * DarkSpace Salvage Yield Roller
 * Choose salvage tier (0-3, 4-6, 7-9, 10+) and roll on the appropriate salvage table.
 */
const pack = game.packs.get("darkspace.rollable-tables");
if (!pack) {
  ui.notifications.error("DarkSpace rollable-tables pack not found.");
} else {
  new Dialog({
    title: "Derelict & Wreck Salvage",
    content: `
      <form class="darkspace-dialog">
        <div class="form-group" style="margin-bottom: 10px;">
          <label><b>Target Hull / Derelict Tier:</b></label>
          <select id="salvage-tier" style="width: 100%;">
            <option value="dsTabSalvage0_3" selected>Tier 0-3 (Scout / Light Craft)</option>
            <option value="dsTabSalvage4_6">Tier 4-6 (Freighter / Corvette)</option>
            <option value="dsTabSalvage7_9">Tier 7-9 (Cruiser / Station Sector)</option>
            <option value="dsTabSalv10plus">Tier 10+ (Battleship / Ancient Derelict)</option>
          </select>
        </div>
      </form>
    `,
    buttons: {
      salvage: {
        icon: '<i class="fas fa-recycle"></i>',
        label: "Cut into Hull & Recover",
        callback: async (html) => {
          const tableId = html.find("#salvage-tier").val();
          const table = await pack.getDocument(tableId);
          if (table) {
            await table.draw({ displayChat: true });
          } else {
            ui.notifications.warn("Salvage table not found.");
          }
        }
      },
      cancel: {
        icon: '<i class="fas fa-times"></i>',
        label: "Cancel"
      }
    },
    default: "salvage"
  }).render(true);
}
